def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value: datetime.timedelta
    :return: int seconds or None
    """
    if value is None:
        return None
    try:
        seconds = value.total_seconds()
    except AttributeError:
        return None
    try:
        return int(seconds)
    except Exception:
        return None

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return: ISO 8601 string representation of the time, or None if value is None.
    """
    if value is None:
        return None
    try:
        import datetime
        if not isinstance(value, datetime.time):
            raise TypeError(f"Expected datetime.time, got {type(value).__name__}")
        return value.isoformat()
    except Exception as exc:
        raise ValueError(f"Failed to dehydrate time value: {exc}") from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        raise ValueError("value cannot be None")
    try:
        lat = getattr(value, 'lat')
        lon = getattr(value, 'lon')
        time = getattr(value, 'time')
    except AttributeError as e:
        raise TypeError("value must have 'lat', 'lon', and 'time' attributes") from e
    if not isinstance(lat, (int, float)):
        raise TypeError("lat must be a numeric type")
    if not isinstance(lon, (int, float)):
        raise TypeError("lon must be a numeric type")
    if hasattr(time, 'isoformat'):
        time_str = time.isoformat()
    else:
        time_str = str(time)
    return {'lat': lat, 'lon': lon, 'time': time_str}

