def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
        """
        Appends a DISCARD message to the output queue.

        :param n: number of records to discard, default = -1 (ALL)
        :param qid: query ID to discard for, default = -1 (last query)
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        """
        # Normalise hook dictionaries
        dehydration_hooks = dehydration_hooks or {}
        hydration_hooks = hydration_hooks or {}

        # Basic type validation
        if not isinstance(n, int):
            raise TypeError(f"n must be an int, got {type(n).__name__}")
        if not isinstance(qid, int):
            raise TypeError(f"qid must be an int, got {type(qid).__name__}")

        # Build the raw message payload
        message = {"type": "DISCARD", "n": n, "qid": qid}

        # Apply dehydration hooks to each value in the message
        for key, value in list(message.items()):
            hook = dehydration_hooks.get(type(value))
            if hook is not None:
                try:
                    message[key] = hook(value)
                except Exception as exc:
                    raise ValueError(
                        f"Dehydration hook for {type(value).__name__} failed: {exc}"
                    ) from exc

        # Append the message to the output queue
        try:
            self._output_queue.append(message)
        except AttributeError as exc:
            raise RuntimeError("Output queue not initialized") from exc

        # Return a Response object that will handle the server reply
        # The Response constructor is assumed to accept the client instance,
        # a dict of handlers, and optional hydration hooks.
        return Response(self, handlers, hydration_hooks)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate the class name
    if not isinstance(name, str) or not name.isidentifier():
        raise TypeError(f"name must be a valid identifier string, got {name!r}")

    # Validate fields iterable
    try:
        iter(fields)
    except TypeError:
        raise TypeError(f"fields must be an iterable, got {fields!r}")

    # Prepare field names and annotations
    field_names = []
    annotations = {}
    for item in fields:
        if isinstance(item, str):
            fname = item
            ftype = 'typing.Any'
        elif isinstance(item, tuple) and len(item) == 2:
            fname, ftype = item
            if not isinstance(fname, str):
                raise TypeError(f"field name must be a string, got {fname!r}")
        else:
            raise TypeError(f"Invalid field specification: {item!r}")

        if not isinstance(fname, str) or not fname.isidentifier():
            raise TypeError(f"Field names must be valid identifiers: {fname!r}")
        if fname in field_names:
            raise TypeError(f"Duplicate field name: {fname!r}")

        field_names.append(fname)
        annotations[fname] = ftype

    # Validate srid_map
    if not isinstance(srid_map, dict):
        raise TypeError(f"srid_map must be a dict, got {srid_map!r}")
    for key in srid_map:
        if key not in field_names:
            raise ValueError(f"srid_map contains unknown field: {key!r}")

    # Build the class dictionary
    class_dict = {
        "__slots__": tuple(field_names),
        "__annotations__": annotations,
        "srid_map": srid_map,
    }

    # Determine the base class; fall back to object if Point is not defined
    try:
        base_cls = Point
    except NameError:
        base_cls = object

    # Create and return the new subclass
    try:
        return type(name, (base_cls,), class_dict)
    except Exception as exc:
        raise RuntimeError(f"Failed to create point type {name!r}: {exc}") from exc

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        if not callable(func):
            raise TypeError("deprecated decorator can only be applied to callable objects")
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Emit a deprecation warning each time the function is called
            with warnings.catch_warnings():
                warnings.simplefilter('always', DeprecationWarning)
                warnings.warn(message, category=DeprecationWarning, stacklevel=3)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    s = s.strip()
    if not s:
        return ()
    # Remove leading 'v' or 'V'
    if s[0] in ('v', 'V'):
        s = s[1:]
    # Strip pre-release or build metadata
    s = s.split('-', 1)[0]
    s = s.split('+', 1)[0]
    parts = s.split('.')
    nums = []
    for part in parts:
        if part == '':
            continue
        part = part.strip()
        # Extract leading digits
        i = 0
        while i < len(part) and part[i].isdigit():
            i += 1
        if i == 0:
            raise ValueError(f"Invalid version component: {part!r} in {s!r}")
        try:
            nums.append(int(part[:i]))
        except ValueError:
            raise ValueError(f"Invalid integer in version component: {part[:i]!r}")
    return tuple(nums)

