def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # If the sequence is a broken class, return it as a single-item list
    try:
        bases = getattr(sequence, "__bases__", ())
    except Exception:
        bases = ()
    if Broken in bases:
        return [sequence]

    cls = sequence.__class__
    # If the sequence is an interface or an implements spec, add it directly
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        # Try to iterate over the sequence; if it fails, treat it as a single item
        try:
            for v in sequence:
                _normalizeargs(v, output)
        except TypeError:
            output.append(sequence)
    return output

def _should_attempt_c_optimizations():
    """Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    import os
    import sys

    # If the PURE_PYTHON environment variable is set, we should not use C optimizations.
    if os.getenv("PURE_PYTHON") is not None:
        return False

    # Detect PyPy implementation.  On PyPy we generally avoid C extensions.
    try:
        if getattr(sys, "implementation", None) and getattr(sys.implementation, "name", "").lower() == "pypy":
            return False
    except Exception:
        # Fallback for older Python versions that may not have sys.implementation
        if "pypy" in sys.version.lower():
            return False

    # Default: attempt C optimizations.
    return True

