    try:
        return not PURE_PYTHON
    except NameError:
        # If PURE_PYTHON is not defined, assume C optimizations are required
        return True

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset context
    self.context = {}

    # Reinitialize bins
    try:
        # If an initial value is defined, use it to fill existing bins
        if hasattr(self, "initial_value") and self.initial_value is not None:
            if hasattr(self, "bins") and isinstance(self.bins, list):
                # Preserve the existing bin count
                self.bins = [self.initial_value for _ in self.bins]
            else:
                # If bins attribute is missing or not a list, create a new list
                if hasattr(self, "n_bins"):
                    self.bins = [self.initial_value] * self.n_bins
                else:
                    # Fallback: empty list
                    self.bins = []
        else:
            # No initial value: use make_bins() if available
            if callable(getattr(self, "make_bins", None)):
                self.bins = self.make_bins()
            else:
                # Fallback: empty list
                self.bins = []
    except Exception as exc:
        # In case of any error, log and set bins to empty list
        if hasattr(self, "logger"):
            self.logger.error(f"Failed to reset bins: {exc}")
        self.bins = []

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    try:
        lines = []
        if header is not None:
            lines.append(str(header))

        # Determine how to iterate over points
        if hasattr(self, "points"):
            points_iter = (
                self.points.items() if isinstance(self.points, dict) else self.points
            )
        else:
            raise AttributeError("Object has no 'points' attribute")

        for item in points_iter:
            # Expect item to be a (coord, value) pair
            if isinstance(item, tuple) and len(item) == 2:
                coord, value = item
            else:
                # Fallback: assume first two elements are coord and value
                coord, value = item[0], item[1]

            # Convert coordinate parts
            if isinstance(coord, (list, tuple, set)):
                coord_parts = [str(c) for c in coord]
            else:
                coord_parts = [str(coord)]

            # Convert value parts
            if isinstance(value, (list, tuple, set)):
                value_parts = [str(v) for v in value]
            else:
                value_parts = [str(value)]

            line = separator.join(coord_parts + value_parts)
            lines.append(line)

        return "\n".join(lines)
    except Exception as exc:
        raise ValueError(f"Failed to convert graph to CSV: {exc}") from exc

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate input
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    # Ensure the object has an 'errors' attribute
    if not hasattr(self, "errors"):
        raise AttributeError("The object has no 'errors' attribute")
    errors = getattr(self, "errors")
    # Ensure the coordinate exists in the errors mapping
    if coord_name not in errors:
        raise KeyError(f"Coordinate '{coord_name}' not found in errors")
    err_obj = errors[coord_name]
    # Handle None or missing error data
    if err_obj is None:
        return []
    # If the error object is an xarray DataArray, use its values
    try:
        # xarray DataArray has .values attribute
        if hasattr(err_obj, "values"):
            err_arr = err_obj.values
        else:
            err_arr = err_obj
    except Exception:
        err_arr = err_obj
    # Convert to numpy array for uniform handling
    import numpy as np
    try:
        arr = np.asarray(err_arr)
    except Exception:
        # If conversion fails, treat as scalar
        arr = np.array([err_arr])
    # If the array is scalar, return [0] if not NaN
    if arr.ndim == 0:
        return [0] if not np.isnan(arr) else []
    # For 1-D arrays, return indices where value is not NaN
    if arr.ndim == 1:
        mask = ~np.isnan(arr)
        return np.where(mask)[0].tolist()
    # For higher-dimensional arrays, flatten and return indices of non-NaN elements
    mask = ~np.isnan(arr.ravel())
    return np.where(mask)[0].tolist()

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # Reject Source sequences outright
        if isinstance(seq, Source):
            return False
        # Direct instance of FillRequest
        if isinstance(seq, FillRequest):
            return True
        # Iterate over sequence to find any FillRequest
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    except TypeError:
        # seq is not iterable
        pass
    return False

