def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    KEY_REGEX = r'^[a-zA-Z0-9_]+$'
    key_pattern = re.compile(KEY_REGEX)

    errors = []

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            if not key_pattern.match(key):
                errors.append({key: f"Label key '{key}' does not match the regex [{KEY_REGEX}]"})

        # Validate value
        def _add_value_error(val):
            errors.append({str(val): 'expected string or bytes-like object'})

        if isinstance(value, (list, tuple)):
            for item in value:
                if not isinstance(item, (str, bytes)):
                    _add_value_error(item)
        else:
            if not isinstance(value, (str, bytes)):
                _add_value_error(value)

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    # Keys that are considered identifying fields when first_level is True
    identifying_keys = {"apiVersion", "kind", "metadata"}

    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Process each element of the list
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            result[key] = new_list
        else:
            # Non-dict and non-list values
            if first_level and key in identifying_keys:
                # Preserve identifying fields at the top level
                result[key] = value
            else:
                result[key] = None
    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    # Helper to update a dict entry
    def _update_dict(target, schema, resp):
        if not isinstance(schema, dict):
            return
        for key, sub_schema in schema.items():
            if key not in target:
                # Initialize based on the type of sub_schema
                if isinstance(sub_schema, dict):
                    target[key] = {}
                elif isinstance(sub_schema, list):
                    target[key] = []
                else:
                    # Primitive field: copy from response if available
                    if isinstance(resp, dict) and key in resp:
                        target[key] = resp[key]
                    continue
            # Recurse into nested structures
            if isinstance(sub_schema, dict):
                if isinstance(resp, dict) and key in resp:
                    _update_dict(target[key], sub_schema, resp[key])
            elif isinstance(sub_schema, list):
                if isinstance(resp, dict) and key in resp:
                    sub_resp = resp[key]
                else:
                    sub_resp = []
                # Ensure target list has enough elements
                for idx, item_schema in enumerate(sub_schema):
                    if idx >= len(target[key]):
                        target[key].append({})
                    item_resp = sub_resp[idx] if isinstance(sub_resp, list) and idx < len(sub_resp) else {}
                    update_last_applied_manifest_dict_from_resp(
                        target[key][idx], item_schema, item_resp
                    )

    # Main logic for list handling
    if isinstance(observer_schema, list) and isinstance(response, list):
        for idx, sub_schema in enumerate(observer_schema):
            # Ensure the list has an element at this index
            if idx >= len(last_applied_manifest):
                last_applied_manifest.append({})
            sub_resp = response[idx] if idx < len(response) else {}
            # If the sub_schema is a dict, delegate to dict updater
            if isinstance(sub_schema, dict):
                _update_dict(last_applied_manifest[idx], sub_schema, sub_resp)
            else:
                # Primitive or unsupported type: copy directly if present
                if isinstance(sub_resp, dict) and isinstance(sub_schema, str):
                    if sub_schema not in last_applied_manifest[idx]:
                        last_applied_manifest[idx][sub_schema] = sub_resp.get(sub_schema)
    elif isinstance(observer_schema, dict):
        # If observer_schema is a dict, treat the whole list as a single dict
        _update_dict(last_applied_manifest, observer_schema, response)
    else:
        # Unsupported schema type; do nothing
        pass

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    if not isinstance(observer_schema, dict):
        raise TypeError("observer_schema must be a dict")
    if not isinstance(response, dict):
        raise TypeError("response must be a dict")

    for key, sub_schema in observer_schema.items():
        # Ensure the key exists in the response
        if key not in response:
            raise KeyError(f"Observed field '{key}' missing in response")

        # If the key is not yet in the manifest, initialize it
        if key not in last_applied_manifest:
            if isinstance(sub_schema, dict):
                # Nested dictionary: create and recurse
                last_applied_manifest[key] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], sub_schema, response[key]
                )
            elif isinstance(sub_schema, list):
                # List of items: create and recurse
                last_applied_manifest[key] = []
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[key], sub_schema, response[key]
                )
            else:
                # Primitive value: copy directly
                last_applied_manifest[key] = response[key]
        else:
            # Key already exists; update nested structures if necessary
            if isinstance(sub_schema, dict):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], sub_schema, response[key]
                )
            elif isinstance(sub_schema, list):
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[key], sub_schema, response[key]
                )
            # For primitives we leave the existing value unchanged

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Default observer schema to use when none is provided
    default_schema = {
        "type": "object",
        "properties": {
            "metadata": {"type": "object"},
            "status": {"type": "object"}
        }
    }

    # If app or its spec is missing, return an empty mapping
    if app is None:
        return {}
    spec = getattr(app, "spec", None)
    if spec is None:
        return {}

    # Existing observer schemas, if any
    observer_schemas = getattr(spec, "observer_schema", {})
    if observer_schemas is None:
        observer_schemas = {}

    # Iterate over the manifest resources
    try:
        resources = getattr(spec, "manifest", [])
        for resource in resources:
            if not isinstance(resource, dict):
                continue
            # Determine a unique identifier for the resource
            name = resource.get("metadata", {}).get("name")
            if not name:
                name = resource.get("kind")
            if not name:
                continue

            # If a custom observer schema is already defined, skip
            if name in observer_schemas:
                continue

            # Check if the resource itself declares an observer schema
            custom_schema = resource.get("observer_schema")
            if custom_schema is not None:
                observer_schemas[name] = custom_schema
            else:
                observer_schemas[name] = default_schema
    except Exception:
        # In case of any unexpected error, return what we have so far
        return observer_schemas

    return observer_schemas

