    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise ValidationError(
            f"Inventory must be a dictionary, got {type(inventory).__name__}"
        )

    # Determine the specification version to use
    spec_version = self.spec_version
    if extract_spec_version:
        type_value = inventory.get("type")
        if type_value is not None:
            try:
                spec_version = self.type_to_version[type_value]
            except Exception:
                # If the type is not recognized, fall back to the default
                pass

    # If the inventory explicitly declares a spec_version, ensure it matches
    if "spec_version" in inventory:
        inv_version = inventory["spec_version"]
        if inv_version != spec_version:
            raise ValidationError(
                f"Inventory spec_version ({inv_version}) does not match "
                f"expected version ({spec_version})"
            )

    # Delegate to the actual validation routine
    try:
        self._validate_inventory(inventory, spec_version)
    except Exception as exc:
        raise ValidationError(f"Inventory validation failed: {exc}") from exc

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic sanity checks
    if prior is None:
        raise ValueError('prior must not be None')
    if not isinstance(prior, InventoryValidator):
        raise TypeError('prior must be an InventoryValidator instance')
    if not hasattr(self, 'inventory') or not hasattr(prior, 'inventory'):
        raise AttributeError('Both self and prior must have an inventory attribute')
    if not isinstance(self.inventory, dict) or not isinstance(prior.inventory, dict):
        raise TypeError('inventory attributes must be dicts')

    # Validate that prior inventory is a subset of the current inventory
    for item, qty in prior.inventory.items():
        if item not in self.inventory:
            raise ValueError(f'Item {item!r} in prior inventory not present in current inventory')
        if qty > self.inventory[item]:
            raise ValueError(f'Quantity of item {item!r} in prior inventory ({qty}) exceeds current inventory ({self.inventory[item]})')

    # Optional version comparison if both objects expose a version attribute
    if hasattr(self, 'version') and hasattr(prior, 'version'):
        try:
            if prior.version >= self.version:
                raise ValueError(f'Prior version {prior.version} must be less than current version {self.version}')
        except Exception:
            # If version comparison fails (e.g., incomparable types), ignore
            pass

    return True

