def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate and normalize indent
    try:
        indent_val = int(indent)
        if indent_val < 0:
            indent_val = 0
    except Exception:
        indent_val = 0

    # Normalize debug flag
    debug_flag = bool(debug)

    # Attempt to create a pretty representation
    rep = None
    try:
        import json
        rep = json.dumps(self, indent=indent_val, default=str)
    except Exception:
        try:
            import pprint
            rep = pprint.pformat(self, indent=indent_val)
        except Exception:
            rep = repr(self)

    # Prepend debug information if requested
    if debug_flag:
        try:
            header = f"{type(self).__name__} at {hex(id(self))}\n"
            rep = header + rep
        except Exception:
            pass

    return rep

def _fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if dt.tzinfo is None:
        raise ValueError("dt must be timezone-aware")
    # If dt is already in this timezone, just return it
    if dt.tzinfo is self:
        return dt
    # Convert dt to this timezone
    try:
        # Use astimezone which handles fold and DST transitions
        return dt.astimezone(self)
    except Exception as exc:
        # Fallback: replace tzinfo directly (may lose DST info)
        return dt.replace(tzinfo=self)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner(*args, **kwargs):
        try:
            # If 'unicode' is defined, we are in Python 2
            unicode
        except NameError:
            # Python 3: return the value unchanged
            return namefunc(*args, **kwargs)
        else:
            # Python 2: ensure the result is a byte string
            result = namefunc(*args, **kwargs)
            if isinstance(result, str):
                return result
            elif isinstance(result, bytes):
                return result
            else:
                raise ValueError("tzname function must return a string or bytes")
    return inner

def get_versions():
    """Get version information or return default if unable to do so."""
    default = "unknown"
    try:
        with open("version.py", "r") as f:
            for line in f:
                if "__version__" in line:
                    # Expect format: __version__ = "x.y.z" or 'x.y.z'
                    parts = line.split("=", 1)
                    if len(parts) == 2:
                        version = parts[1].strip()
                        # Remove surrounding quotes or parentheses
                        return version.strip('\'"()')
        # If we reach here, __version__ not found
        return default
    except Exception:
        # Any error (file not found, permission, etc.) results in default
        return default

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate input types
    if not isinstance(pieces, (list, tuple)):
        raise TypeError('pieces must be a list or tuple')
    if not isinstance(style, str):
        raise TypeError('style must be a string')

    # Helper to safely fetch a piece or return None
    def _get(index):
        try:
            return pieces[index]
        except IndexError:
            return None

    # Render according to requested style
    if style == 'semver':
        major = _get(0)
        minor = _get(1)
        patch = _get(2)
        if major is None or minor is None or patch is None:
            raise ValueError('semver style requires at least major, minor, and patch numbers')
        version = f"{major}.{minor}.{patch}"
        pre = _get(3)
        build = _get(4)
        if pre:
            version += f"-{pre}"
        if build:
            version += f"+{build}"
        return version

    elif style == 'short':
        major = _get(0)
        minor = _get(1)
        if major is None or minor is None:
            raise ValueError('short style requires major and minor numbers')
        return f"{major}.{minor}"

    elif style == 'full':
        if not pieces:
            return ''
        return '.'.join(str(p) for p in pieces)

    elif style == 'tuple':
        return tuple(pieces)

    else:
        raise ValueError(f"Unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        if '+' in pieces:
            return '.'
