    except Exception:
        # If pieces is not iterable or any other error occurs, default to '+'
        return '+'

def register_vcs_handler(vcs, method):  # tyoe: (str, str) -> typing.Callable  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if not isinstance(vcs, str) or not isinstance(method, str):
            raise TypeError("vcs and method must be strings")
        if not callable(f):
            raise TypeError("decorated object must be callable")
        global HANDLERS
        if 'HANDLERS' not in globals():
            HANDLERS = {}
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Determine the collection of objects to validate
    try:
        if hasattr(self._storage_root, "values"):
            objects = list(self._storage_root.values())
        else:
            objects = list(self._storage_root)
    except Exception as exc:
        raise TypeError("self._storage_root must be an iterable or mapping of objects") from exc

    num_objects = 0
    good_objects = 0

    for obj in objects:
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested
        if validate_objects:
            try:
                if hasattr(obj, "validate") and callable(obj.validate):
                    obj.validate()
            except Exception as e:
                is_valid = False
                if show_warnings:
                    print(f"[WARNING] Validation failed for object {obj!r}: {e}")

        # Check the digest if requested and the object passed validation
        if check_digests and is_valid:
            try:
                # Expect the object to expose a digest() method and a stored_digest attribute
                if hasattr(obj, "digest") and callable(obj.digest) and hasattr(obj, "stored_digest"):
                    current_digest = obj.digest()
                    if current_digest != obj.stored_digest:
                        is_valid = False
                        if show_warnings:
                            print(f"[WARNING] Digest mismatch for object {obj!r}")
                else:
                    # If the object does not provide digest info, skip this check
                    pass
            except Exception as e:
                is_valid = False
                if show_warnings:
                    print(f"[WARNING] Digest check failed for object {obj!r}: {e}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str) or not version:
        return ""
    # Preserve leading zeros if present
    stripped = version.lstrip('0')
    # If the string is all zeros, stripped will be empty; treat as zero
    if stripped == "":
        stripped = "0"
    try:
        num = int(version)
    except ValueError:
        # If not a pure integer, return the original string unchanged
        return version
    next_num = num + 1
    # Determine width to preserve leading zeros
    width = len(version) if version.lstrip('0') != "" else len(version)
    # If the original had leading zeros, use zfill to maintain width
    if version.lstrip('0') != "":
        return str(next_num).zfill(width)
    return str(next_num)

