def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types
    if response is None:
        raise ValueError("response must not be None")
    if not isinstance(response, list):
        raise TypeError(f"response must be a list, got {type(response).__name__}")
    if not isinstance(max_results, int):
        raise TypeError(f"max_results must be an int, got {type(max_results).__name__}")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Generator that yields slices of the list
    def _generator():
        for start in range(0, len(response), max_results):
            yield response[start:start + max_results]

    return _generator()

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("Input must be an iterable of dictionaries, got None")
    try:
        iterator = iter(dicts)
    except TypeError as exc:
        raise TypeError("Input must be an iterable of dictionaries") from exc

    result = {}
    for d in iterator:
        if not isinstance(d, dict):
            raise TypeError(f"All elements must be dicts, got {type(d).__name__}")
        for key, value in d.items():
            if key in result:
                try:
                    result[key] += value
                except TypeError as exc:
                    raise TypeError(f"Cannot sum values for key {key!r}") from exc
            else:
                result[key] = value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    if not url_args:
        return url

    if not isinstance(url_args, dict):
        raise TypeError('url_args must be a dict')

    result = url
    for key, value in url_args.items():
        if value is None:
            continue
        placeholder_braces = '{' + str(key) + '}'
        placeholder_colon = ':' + str(key)
        result = result.replace(placeholder_braces, str(value))
        result = result.replace(placeholder_colon, str(value))

    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Direct None check
    if val is None:
        return True
    # Only strings are considered for further checks
    if not isinstance(val, str):
        return False
    # Strip whitespace for accurate comparison
    stripped = val.strip()
    # Empty string is considered None-like
    if not stripped:
        return True
    # Common textual representations of None
    return stripped.lower() in ("none", "null", "nan")

