def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    # Remove leading and trailing single or double quotes
    return re.sub(r'^[\'"]+|[\'"]+$', '', name)

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    # Validate the input
    if ignored is None:
        ignored = []
    if not isinstance(ignored, (list, tuple)):
        raise TypeError("ignored must be a list or tuple")
    # Build the git command to list ignored files
    cmd = ['git', 'ls-files', '--others', '--ignored', '--exclude-standard']
    try:
        output = subprocess.check_output(cmd, stderr=subprocess.STDOUT, universal_newlines=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Git command failed: {e.output}") from e
    # Convert output to a sorted list of file names
    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    # Return a comma-separated string of the ignored files
    return ','.join(files)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        addr_infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for info in addr_infos:
        family, _, _, _, sockaddr = info
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip.startswith("127."):
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            # IPv6 loopback can be represented in several ways
            if ip in ("::1", "0:0:0:0:0:0:0:1"):
                return True
    return False

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    if not hasattr(find_paths, "__iter__") or isinstance(find_paths, (str, bytes)):
        raise TypeError(f"find_paths must be an iterable of strings, got {type(find_paths)}")
    transformed = []
    for item in find_paths:
        if not isinstance(item, str):
            try:
                item = str(item)
            except Exception as exc:
                raise TypeError(f"find_paths elements must be convertible to str, got {type(item)}") from exc
        if ":" in item:
            # Assume this is already a pattern; leave unchanged
            transformed.append(item)
        else:
            # Convert fragment to glob pattern
            transformed.append(f"sh:**/*{item}*/**")
    return transformed

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Only consider Windows platforms
        if os.name != 'nt':
            return False
        # Git Bash sets OSTYPE to 'msys'
        if os.environ.get('OSTYPE', '').startswith('msys'):
            return True
        # Git Bash also sets MSYSTEM to 'MINGW64' or 'MINGW32'
        if os.environ.get('MSYSTEM', '').startswith('MINGW'):
            return True
        return False
    except Exception:
        return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    config_filename = os.path.expanduser(config_filename)
    if not overwrite and os.path.isfile(config_filename):
        return
    try:
        dir_name = os.path.dirname(config_filename)
        if dir_name:
            os.makedirs(dir_name, exist_ok=True)
    except OSError:
        if not os.path.isdir(dir_name):
            raise
    with open(config_filename, 'w') as f:
        f.write(rendered_config)
    os.chmod(config_filename, mode)

