def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import logging
    import json
    try:
        import toml
    except ImportError:
        toml = None
    try:
        import yaml
    except ImportError:
        yaml = None

    def _resolve_env_vars(obj):
        if isinstance(obj, dict):
            return {k: _resolve_env_vars(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_resolve_env_vars(v) for v in obj]
        if isinstance(obj, str):
            return os.path.expandvars(obj)
        return obj

    config_map = {}
    error_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as exc:
            record = logging.LogRecord(
                name=filename,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to read file: {exc}',
                args=(),
                exc_info=exc
            )
            error_records.append(record)
            continue

        ext = os.path.splitext(filename)[1].lower()
        parsed = None
        try:
            if ext == '.toml':
                if toml is None:
                    raise ImportError('toml module not available')
                parsed = toml.loads(content)
            elif ext in ('.yaml', '.yml'):
                if yaml is None:
                    raise ImportError('yaml module not available')
                parsed = yaml.safe_load(content)
            elif ext == '.json':
                parsed = json.loads(content)
            else:
                # Try yaml as fallback
                if yaml is None:
                    raise ImportError('yaml module not available')
                parsed = yaml.safe_load(content)
        except Exception as exc:
            record = logging.LogRecord(
                name=filename,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to parse file: {exc}',
                args=(),
                exc_info=exc
            )
            error_records.append(record)
            continue

        if not isinstance(parsed, dict):
            record = logging.LogRecord(
                name=filename,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg='Parsed configuration is not a dictionary',
                args=(),
                exc_info=None
            )
            error_records.append(record)
            continue

        if overrides:
            try:
                parsed.update(overrides)
            except Exception as exc:
                record = logging.LogRecord(
                    name=filename,
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Failed to apply overrides: {exc}',
                    args=(),
                    exc_info=exc
                )
                error_records.append(record)
                continue

        if resolve_env:
            try:
                parsed = _resolve_env_vars(parsed)
            except Exception as exc:
                record = logging.LogRecord(
                    name=filename,
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Failed to resolve environment variables: {exc}',
                    args=(),
                    exc_info=exc
                )
                error_records.append(record)
                continue

        config_map[filename] = parsed

    return config_map, error_records

