@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Retrieve the mapping of supported handlers.  Subclasses may
        # override this attribute; if it is missing we treat it as empty.
        handlers = getattr(cls, "_protocol_handlers", {})
        if protocol_version is None:
            # Return a shallow copy to prevent accidental mutation.
            return dict(handlers)

        # Validate the supplied protocol_version.
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
            )
        if len(protocol_version) != 2:
            raise TypeError(
                f"protocol_version tuple must contain exactly two elements, got {len(protocol_version)}"
            )
        major, minor = protocol_version
        if not (isinstance(major, int) and isinstance(minor, int)):
            raise TypeError(
                f"protocol_version elements must be integers, got {type(major).__name__} and {type(minor).__name__}"
            )

        # Return a dictionary containing the handler if it exists.
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        return {}

@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        if values is None:
            raise ValueError("values cannot be None")
        # If a single string is passed, treat it as a single raw bookmark
        if isinstance(values, str):
            values = [values]
        try:
            iterator = iter(values)
        except TypeError:
            raise TypeError("values must be an iterable of strings")
        bookmarks = []
        for raw in iterator:
            if not isinstance(raw, str):
                raise TypeError(f"Bookmark value must be a string, got {type(raw).__name__}")
            try:
                # Prefer a dedicated from_raw method if available
                bookmark = Bookmark.from_raw(raw)
            except AttributeError:
                # Fallback: try to instantiate Bookmark directly
                try:
                    bookmark = Bookmark(raw)
                except Exception as e:
                    raise ValueError(f"Failed to create Bookmark from raw value: {raw}") from e
            except Exception as e:
                raise ValueError(f"Failed to create Bookmark from raw value: {raw}") from e
            bookmarks.append(bookmark)
        return cls(bookmarks)

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Basic type checks
    if not isinstance(iface, type):
        raise TypeError('iface must be a class or interface')
    if not isinstance(candidate, type) and not hasattr(candidate, '__class__'):
        raise TypeError('candidate must be a class or an instance')

    # Resolve the candidate class
    cand_cls = candidate if isinstance(candidate, type) else candidate.__class__

    # If candidate is already a subclass of iface, it's valid
    try:
        if issubclass(cand_cls, iface):
            return True
    except TypeError:
        # cand_cls might not be a class (unlikely after checks)
        pass

    # Gather required attributes from iface (ignore private and special)
    required_attrs = [attr for attr in dir(iface) if not attr.startswith('_')]
    missing = []

    for attr in required_attrs:
        # Skip abstract methods if iface uses ABCMeta
        if hasattr(iface, '__abstractmethods__') and attr in iface.__abstractmethods__:
            continue
        if not hasattr(cand_cls, attr):
            missing.append(attr)

    if missing:
        if tentative:
            return False
        raise ValueError(
            f'Candidate {candidate!r} does not implement interface {iface!r}: missing {missing}'
        )

    return True

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised."""
    if key in self:
        return super().pop(key)
    if default is not __marker:
        return default
    raise KeyError(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # The LRU cache is expected to store items in an OrderedDict named `_cache`.
    # If the attribute is missing, raise an informative error.
    if not hasattr(self, "_cache"):
        raise AttributeError("LRUCache instance has no `_cache` attribute")
    try:
        # `popitem(last=False)` removes the first item (least recently used).
        return self._cache.popitem(last=False)
    except KeyError:
        # If the cache is empty, raise a KeyError to match dict.popitem() semantics.
        raise KeyError("Cache is empty")

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        key, value = dict.popitem(self)
        return key, value
    except KeyError:
        raise KeyError('dict is empty')

