    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("'tag' expects a string")
    tag = tag.strip()
    if not tag:
        return False
    # Allowed characters: letters, digits, underscore, hyphen
    import re
    pattern = re.compile(r'^[A-Za-z0-9_-]+$')
    return bool(pattern.match(tag))

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    # Ensure we are working with an ElementTree element
    try:
        iterator = iter(node)
    except TypeError:
        raise TypeError("Expected an ElementTree element or iterable of elements")
    result = {}
    for child in iterator:
        key = child.tag
        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[key] = [existing, child]
        else:
            result[key] = child
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None

    result: Dict[str, str] = {}

    # Try JSON format first
    try:
        data = json.loads(document)
        links = data.get("links", [])
        for link in links:
            rel = link.get("rel")
            href = link.get("href")
            if rel == "hcard":
                result["hcard_url"] = href
            elif rel == "avatar":
                result["avatar_url"] = href
        if "subject" in data:
            result["subject"] = data["subject"]
        if result:
            return result
    except Exception:
        pass

    # Fallback to XRD (XML) format
    try:
        root = ET.fromstring(document)
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        subject_el = root.find("xrd:Subject", ns)
        if subject_el is not None:
            result["subject"] = subject_el.text
        for link in root.findall("xrd:Link", ns):
            rel = link.attrib.get("rel")
            href = link.attrib.get("href")
            if rel == "hcard":
                result["hcard_url"] = href
            elif rel == "avatar":
                result["avatar_url"] = href
        return result if result else None
    except Exception:
        return None

