@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise IRValidatorException("yaml_file argument must be supplied")

    path = Path(yaml_file)
    if not path.is_file():
        raise IRValidatorException(f"File not found: {yaml_file}")

    try:
        with path.open("r") as f:
            data = yaml.safe_load(f)
    except Exception as e:
        raise IRValidatorException(f"Error loading YAML file: {e}")

    if data is None:
        raise IRValidatorException("YAML file is empty or could not be parsed")

    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a mapping at the root")

    # Determine required fields; allow subclasses to override via a class attribute
    required_fields = getattr(cls, "required_fields", ["name", "version", "data"])
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

    return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    for arg in getattr(self, "args", []):
        # Skip non-option arguments
        if not isinstance(arg, _BaseOpt):
            continue

        # Attempt to get a value from the spec first
        spec_val = None
        try:
            spec_val = self.spec.get(arg.name)
        except Exception:
            # If spec is not dict-like or key access fails, ignore
            pass

        if spec_val is not None:
            defaults[arg.name] = spec_val
        else:
            # Fallback to the option's own default if it exists
            if not isinstance(arg.default, NoDefault):
                defaults[arg.name] = arg.default

        # Handle nested dictionary options by recursing into their scheme
        if isinstance(arg, DictOption) and getattr(arg, "scheme", None):
            nested = arg.scheme.get_spec_defaults()
            if nested:
                defaults[arg.name] = nested

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    # Example mapping: {'old_option': 'new_option'}
    return {}

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    # The command options are expected to be stored in a dictionary
    # mapping command names to lists of option specifications.
    try:
        options = self._command_options[command_name]
    except AttributeError:
        raise AttributeError(
            "The object does not have a '_command_options' attribute"
        ) from None
    except KeyError:
        raise ValueError(f"Unknown command name: {command_name}") from None
    # Return a shallow copy to prevent accidental modification of the
    # internal data structure.
    return list(options)

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Ensure the internal specification dictionary exists
    if not hasattr(self, "_specs"):
        raise AttributeError("The object does not contain a '_specs' attribute.")
    # Retrieve the command-specific specification
    try:
        command_spec = self._specs[command_name]
    except KeyError:
        raise ValueError(f"Command '{command_name}' not found in specifications.")
    # Retrieve the option specification
    try:
        return command_spec[argument_name]
    except KeyError:
        raise ValueError(f"Option '{argument_name}' not found for command '{command_name}'.")

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    # Ensure args is a mapping of argument names to values
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")

    # Retrieve the list or set of required argument names
    required = getattr(self, 'required_args', None)
    if required is None:
        # No required arguments defined; nothing to validate
        return

    # Ensure required is iterable
    try:
        iter(required)
    except TypeError:
        raise TypeError("self.required_args must be an iterable of argument names")

    # Identify any missing required arguments
    missing = [name for name in required
               if name not in args or args[name] is None]

    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    # Basic type checks
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(options_spec, (list, tuple)):
        raise TypeError("options_spec must be a list or tuple")
    if not isinstance(args, dict):
        raise TypeError("args must be a dict")

    required = []

    for opt in options_spec:
        # Extract option name
        if isinstance(opt, dict):
            name = opt.get("name")
            cond = opt.get("required_when")
        else:
            # Fallback for objects with attributes
            name = getattr(opt, "name", None)
            cond = getattr(opt, "required_when", None)

        if not name:
            continue  # skip options without a name

        if cond is None:
            continue  # no conditional requirement

        # Evaluate the condition
        try:
            if isinstance(cond, dict):
                # Mapping of command names to callables or booleans
                cond_val = cond.get(command_name)
                if cond_val is None:
                    continue
                if callable(cond_val):
                    if cond_val(args):
                        required.append(name)
                else:
                    if cond_val:
                        required.append(name)
            elif callable(cond):
                if cond(args):
                    required.append(name)
            else:
                # Treat non-callable as a boolean flag
                if cond:
                    required.append(name)
        except Exception:
            # If condition evaluation fails, ignore this option
            continue

    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Ensure args is a dictionary
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict (got {type(args).__name__})")

    # Retrieve argument specifications from parsed YAML
    arg_specs = self.parsed_yaml.get('args', {})
    if not isinstance(arg_specs, dict):
        raise TypeError(f"parsed_yaml['args'] must be a dict (got {type(arg_specs).__name__})")

    for arg_name, value in args.items():
        # Get the length constraint for this argument, if any
        spec = arg_specs.get(arg_name, {})
        if not isinstance(spec, dict):
            raise TypeError(f"spec for argument '{arg_name}' must be a dict (got {type(spec).__name__})")

        length = spec.get('length')
        if length is None:
            # No length constraint specified; skip validation
            continue

        # Validate that the length constraint is an integer
        if not isinstance(length, int):
            raise TypeError(
                f"length for argument '{arg_name}' must be an int (got {type(length).__name__})"
            )
        if length < 0:
            raise ValueError(
                f"length for argument '{arg_name}' must be non-negative (got {length})"
            )

        # Skip validation if the value is None
        if value is None:
            continue

        # Attempt to determine the length of the value
        try:
            val_len = len(value)
        except Exception:
            # If the value has no length (e.g., an int), skip validation
            continue

        if val_len > length:
            raise ValueError(
                f"Argument '{arg_name}' length {val_len} exceeds maximum allowed {length}"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the argument definitions from the parsed YAML configuration.
    arg_defs = self.parsed_yaml.get('args', {})
    # Iterate over each provided argument and its value.
    for arg_name, value in args.items():
        # Locate the definition for this argument.
        if isinstance(arg_defs, dict):
            arg_def = arg_defs.get(arg_name)
        else:  # assume a list of single‑item dicts
            arg_def = None
            for item in arg_defs:
                if isinstance(item, dict) and arg_name in item:
                    arg_def = item[arg_name]
                    break
        # If no definition is found, skip validation for this argument.
        if not arg_def:
            continue
        # If the definition does not specify choices, skip validation.
        choices = arg_def.get('choices')
        if choices is None:
            continue
        # Validate that the provided value is one of the allowed choices.
        if value not in choices:
            raise ValueError(
                f"Invalid value for argument '{arg_name}': {value}. "
                f"Expected one of {choices}"
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Validate input type
    if isinstance(args, dict):
        for key, value in args.items():
            # Build attribute names for min and max
            min_attr = f"{key}_min"
            max_attr = f"{key}_max"
            if hasattr(self, min_attr) and hasattr(self, max_attr):
                min_val = getattr(self, min_attr)
                max_val = getattr(self, max_attr)
                # Skip validation if value is None
                if value is None:
                    continue
                try:
                    if value < min_val or value > max_val:
                        raise ValueError(
                            f"Argument '{key}' with value {value} is out of bounds "
                            f"[{min_val}, {max_val}]"
                        )
                except TypeError as exc:
                    raise TypeError(
                        f"Cannot compare value of argument '{key}' with min/max bounds"
                    ) from exc
            else:
                # If no specific min/max attributes, skip validation for this key
                continue
    elif isinstance(args, (list, tuple)):
        # Use generic min and max attributes if defined
        if hasattr(self, "min") and hasattr(self, "max"):
            min_val = getattr(self, "min")
            max_val = getattr(self, "max")
            for idx, value in enumerate(args):
                if value is None:
                    continue
                try:
                    if value < min_val or value > max_val:
                        raise ValueError(
                            f"Argument at index {idx} with value {value} is out of bounds "
                            f"[{min_val}, {max_val}]"
                        )
                except TypeError as exc:
                    raise TypeError(
                        f"Cannot compare value at index {idx} with min/max bounds"
                    ) from exc
        else:
            raise AttributeError(
                "No generic 'min' and 'max' attributes defined for validation"
            )
    else:
        raise TypeError("args must be a dict or a list/tuple of values")

    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Validate inputs
    if not isinstance(subcommand, str) or not subcommand:
        raise ValueError("subcommand must be a non-empty string")
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("type_name must be a non-empty string")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("option_name must be a non-empty string")
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dict mapping keys to types or default values")

    # Create a namedtuple type for the complex argument
    from collections import namedtuple
    ComplexType = namedtuple(f"{subcommand}_{type_name}", spec_option.keys())

    def _parser(value):
        """
        Parse a string of the form key1=val1,key2=val2 into a ComplexType instance.
        """
        if not isinstance(value, str):
            raise ValueError(f"Expected string for {option_name}, got {type(value).__name__}")

        parts = value.split(',')
        parsed = {}
        for part in parts:
            if '=' not in part:
                raise ValueError(f"Invalid format for {option_name}: '{part}'. Expected key=value.")
            key, val = part.split('=', 1)
            key = key.strip()
            val = val.strip()
            if key not in spec_option:
                raise ValueError(f"Unexpected key '{key}' for {option_name}")
            cast = spec_option[key]
            try:
                if isinstance(cast, type):
                    parsed[key] = cast(val)
                else:
                    # If cast is a default value, use it directly
                    parsed[key] = val
            except Exception as exc:
                raise ValueError(f"Could not cast value for key '{key}': {exc}") from exc

        # Fill in defaults for missing keys
        for key, cast in spec_option.items():
            if key not in parsed:
                if isinstance(cast, type):
                    parsed[key] = cast()
                else:
                    parsed[key] = cast

        return ComplexType(**parsed)

    return _parser

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :return: The updated dictionary
        """
        if vars_dict is None:
            raise ValueError("vars_dict must be a dictionary")
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

        if extra_vars is None:
            return vars_dict

        # If extra_vars is a dict, merge directly
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # If extra_vars is a list, iterate over its elements
        if isinstance(extra_vars, list):
            for item in extra_vars:
                if isinstance(item, dict):
                    vars_dict.update(item)
                elif isinstance(item, (list, tuple)) and len(item) == 2:
                    key, value = item
                    vars_dict[key] = value
                else:
                    raise ValueError(
                        f"Unsupported item type in extra_vars list: {type(item).__name__}"
                    )
            return vars_dict

        # Unsupported type for extra_vars
        raise TypeError(
            f"extra_vars must be a dict or list, got {type(extra_vars).__name__}"
        )

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in place.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of arguments to be casted
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")

    # Retrieve the parser configuration for the given command name.
    parser_cfg = getattr(self, "parsers", {}).get(parser_name)
    if parser_cfg is None:
        raise KeyError(f"Parser configuration for '{parser_name}' not found")

    # Support two common parser configuration styles:
    # 1. A mapping of option names to callable type converters.
    # 2. An object with an 'options' attribute that is an iterable of
    #    objects having 'name' and 'type' (or 'convert') attributes.
    if hasattr(parser_cfg, "options"):
        # Style 2
        for opt in parser_cfg.options:
            name = getattr(opt, "name", None)
            if name is None:
                continue
            if name in values_dict:
                try:
                    # Prefer a 'convert' method if available, otherwise use 'type'.
                    convert_func = getattr(opt, "convert", None) or getattr(opt, "type", None)
                    if convert_func is None:
                        raise AttributeError(f"No conversion function for option '{name}'")
                    values_dict[name] = convert_func(values_dict[name])
                except Exception as exc:
                    raise ValueError(
                        f"Failed to convert argument '{name}' with value "
                        f"'{values_dict[name]}' for parser '{parser_name}': {exc}"
                    ) from exc
    else:
        # Style 1
        for name, convert_func in parser_cfg.items():
            if name in values_dict:
                try:
                    values_dict[name] = convert_func(values_dict[name])
                except Exception as exc:
                    raise ValueError(
                        f"Failed to convert argument '{name}' with value "
                        f"'{values_dict[name]}' for parser '{parser_name}': {exc}"
                    ) from exc
    # The function modifies values_dict in place; no return value is needed.

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(d, parent_key=''):
        flat = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    if not isinstance(plugin_dir, str) or not os.path.isdir(plugin_dir):
        raise ValueError("plugin_dir must be a valid directory path")

    # Try to load plugin.json first
    spec_path = os.path.join(plugin_dir, "plugin.json")
    if not os.path.isfile(spec_path):
        # Fallback to plugin.yaml if json not found
        spec_path = os.path.join(plugin_dir, "plugin.yaml")
        if not os.path.isfile(spec_path):
            raise FileNotFoundError("No plugin spec file found in the directory")

    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            if spec_path.endswith('.json'):
                data = json.load(f)
            else:
                # Attempt to load YAML if available
                try:
                    import yaml
                    data = yaml.safe_load(f)
                except Exception as e:
                    raise ValueError(f"Failed to parse YAML spec: {e}")
    except Exception as e:
        raise ValueError(f"Error reading plugin spec: {e}")

    if not isinstance(data, dict):
        raise ValueError("Plugin spec must be a dictionary at the top level")

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = 'CONFIG_PATH'
    # Ensure we have a config path to inject
    if not hasattr(self, 'config_path') or self.config_path is None:
        raise ValueError('config_path attribute is not set')
    # Only set the environment variable if it is not already defined
    if env_var not in os.environ:
        try:
            os.environ[env_var] = str(self.config_path)
        except Exception as exc:
            # Log the error and re‑raise to make the failure obvious
            logger.error('Failed to set environment variable %s: %s', env_var, exc)
            raise
    return None

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    if root == "":
        raise ValueError("Root cannot be an empty string")
    abs_path = os.path.abspath(path)
    abs_root = os.path.abspath(root)
    try:
        rel = os.path.relpath(abs_path, abs_root)
    except ValueError as exc:
        raise ValueError(f"Cannot strip root: {exc}") from exc
    if rel == "." or rel == "":
        return ""
    if rel.startswith(".."):
        raise ValueError(f"Path '{path}' is not under root '{root}'")
    return rel
